import{_ as t,o as r,c as e,a6 as l}from"./chunks/framework.BrkgobfX.js";const m=JSON.parse('{"title":"回顾与展望","description":"把十篇收成一页：RSI 的五级台阶各走到了哪里，哪些是实验室与作者的自述、哪些有独立证据，为什么还没“爆炸”，护栏画在哪，以及接下来值得盯的信号。","frontmatter":{"title":"回顾与展望","description":"把十篇收成一页：RSI 的五级台阶各走到了哪里，哪些是实验室与作者的自述、哪些有独立证据，为什么还没“爆炸”，护栏画在哪，以及接下来值得盯的信号。","source":"https://daiw.org/manual/rsi/recap"},"headers":[],"relativePath":"manual/llm/rsi/recap.md","filePath":"manual/llm/rsi/recap.md"}'),n={name:"manual/llm/rsi/recap.md"};function o(s,a,i,d,h,g){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="回顾与展望" tabindex="-1">回顾与展望 <a class="header-anchor" href="#回顾与展望" aria-label="Permalink to &quot;回顾与展望&quot;">​</a></h1><blockquote><p>把十篇收成一页：RSI 的五级台阶各走到了哪里，哪些是实验室与作者的自述、哪些有独立证据，为什么还没“爆炸”，护栏画在哪，以及接下来值得盯的信号。</p></blockquote><p>十篇读下来，“递归自我改进”这个听起来像科幻的词，可以落成一句朴素的话：<strong>AI 已经在帮人造 AI，但离“自己造出更强的自己”还隔着好几道关</strong>。这一篇把全书收成一页。</p><h2 id="五级台阶走到了哪" tabindex="-1">五级台阶走到了哪 <a class="header-anchor" href="#五级台阶走到了哪" aria-label="Permalink to &quot;五级台阶走到了哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>台阶</th><th>改的是什么</th><th>2026 年的状态</th><th>篇目</th></tr></thead><tbody><tr><td>1</td><td>单次的答案</td><td>已是日常：写完再检查、失败再重试</td><td><a href="/Front2Full/manual/llm/rsi/rsi-ladder">五级台阶</a></td></tr><tr><td>2</td><td>训练信号</td><td>自己出题、自反馈与可验证奖励已进入主流旗舰训练，模型坍塌与奖励黑客是主要风险</td><td><a href="/Front2Full/manual/llm/rsi/self-play-data">自博弈</a>、<a href="/Front2Full/manual/llm/rsi/self-rewarding">自我奖励</a></td></tr><tr><td>3</td><td>脚手架与代码</td><td>能改写自身代码的 Agent 在实验里有效，档案库式的开放探索胜过贪心；作弊与沙箱是绕不开的问题</td><td><a href="/Front2Full/manual/llm/rsi/self-modifying-agents">改自己的代码</a></td></tr><tr><td>4</td><td>研发环节</td><td>发明算法、优化内核与调度、写实验代码已经在实验室内部大量使用</td><td><a href="/Front2Full/manual/llm/rsi/algorithm-discovery">AlphaEvolve 一族</a>、<a href="/Front2Full/manual/llm/rsi/automated-research">自动化研发</a></td></tr><tr><td>5</td><td>整个研究闭环</td><td>还没有：选题、判断结果、决定取舍仍由人拍板</td><td><a href="/Front2Full/manual/llm/rsi/automated-research">自动化研发</a></td></tr></tbody></table><p>越往上，改动的影响越大，验收越难——这条线索从第二篇贯穿到最后一篇。</p><h2 id="哪些有独立证据-哪些还是自述" tabindex="-1">哪些有独立证据，哪些还是自述 <a class="header-anchor" href="#哪些有独立证据-哪些还是自述" aria-label="Permalink to &quot;哪些有独立证据，哪些还是自述&quot;">​</a></h2><p>这个方向的数字大多来自实验室与论文作者本身，读的时候要分清：</p><ul><li><strong>有外部测量的</strong>：METR 的任务时间跨度等第三方评测，给出了“能力曲线很陡”的相对独立的证据（<a href="/Front2Full/manual/llm/rsi/measuring-rsi">怎么量进展</a>）。</li><li><strong>实验室自述的</strong>：“多少代码由模型写”“内部研发被自动化了多少”“实际加速了几倍”，以及各家系统卡里的研发能力评估，都是官方口径，外界目前难以核实。</li><li><strong>论文作者报告的</strong>：自博弈、自我奖励、自改代码、算法发现等方向的大部分成绩，只有少数被别的团队复现或当作基线重跑过。</li></ul><p>把这些读数拼在一起，画面并不矛盾：能力在陡峭上升，但按实验室自己的估计，到 2026 年夏秋实际的研发加速还不到 2 倍。</p><h2 id="为什么还没-爆炸" tabindex="-1">为什么还没“爆炸” <a class="header-anchor" href="#为什么还没-爆炸" aria-label="Permalink to &quot;为什么还没“爆炸”&quot;">​</a></h2><p><a href="/Front2Full/manual/llm/rsi/bottlenecks">瓶颈</a>一篇拆出了五道关：<strong>算力</strong>（实验得真跑）、<strong>验证</strong>（怎么知道改对了）、<strong>数据</strong>（发现盲区仍要靠人）、<strong>研究品味</strong>（选什么题、信哪个结果），以及<strong>收益递减</strong>。乐观派认为软件层面的研发回报足以撑起加速，怀疑派认为算力与验证会一直是硬约束——两边的论据都摆在那一篇里，本书不替读者下结论。</p><h2 id="护栏画在哪" tabindex="-1">护栏画在哪 <a class="header-anchor" href="#护栏画在哪" aria-label="Permalink to &quot;护栏画在哪&quot;">​</a></h2><p>三家前沿实验室都在各自的安全框架里为“AI 自动化 AI 研发”单独画了线，临界点大致落在“研发被完全自动化”或“进展速度因此翻倍”这一类位置；2026 年下半年，一些实验室开始把刹车从文件落到行动上。监控内部使用、确保下一代仍然对齐，是最难的两件事（<a href="/Front2Full/manual/llm/rsi/safety-governance">风险与治理</a>）。</p><h2 id="接下来值得盯的信号" tabindex="-1">接下来值得盯的信号 <a class="header-anchor" href="#接下来值得盯的信号" aria-label="Permalink to &quot;接下来值得盯的信号&quot;">​</a></h2><ul><li><strong>时间跨度的翻倍速度</strong>会不会继续加快；</li><li>实验室公布的<strong>研发加速倍数</strong>会不会越过 2 倍，以及有没有独立机构能核实；</li><li>第 5 级台阶的第一个像样的例子：<strong>由 AI 主导、从选题到验证完整走完</strong>的一项研发成果；</li><li>安全框架里的<strong>研发阈值</strong>有没有被宣布越过，以及随之而来的措施；</li><li>算力与验证这两道关，有没有出现绕开它们的新方法。</li></ul><h2 id="继续读什么" tabindex="-1">继续读什么 <a class="header-anchor" href="#继续读什么" aria-label="Permalink to &quot;继续读什么&quot;">​</a></h2><ul><li><strong>想补大模型的底子</strong>：<a href="https://daiw.org/manual/llm-anatomy" target="_blank" rel="noreferrer">《AI 大模型解构》</a>。</li><li><strong>想看 2026 年前沿开源旗舰在后训练中怎样使用自反馈强化学习与大规模验证环境</strong>：<a href="https://daiw.org/manual/deepseek-v4-flash" target="_blank" rel="noreferrer">《DeepSeek V4.1 Flash 深度解析》</a>、<a href="https://daiw.org/manual/qwen3-8-max" target="_blank" rel="noreferrer">《Qwen3.8-Max 深度解析》</a>、<a href="https://daiw.org/manual/kimi-k3" target="_blank" rel="noreferrer">《Kimi K3 深度解析》</a>。</li><li><strong>想看 Agent 是怎么搭起来的</strong>：<a href="https://daiw.org/manual/llm-to-agent" target="_blank" rel="noreferrer">《从 LLM 到 Coding Agent》</a>。</li><li><strong>想看已经“参与造自己”的编码 Agent 在用户手里长什么样</strong>：<a href="https://daiw.org/manual/claude-code" target="_blank" rel="noreferrer">《Claude Code 中文手册》</a>、<a href="https://daiw.org/manual/codex" target="_blank" rel="noreferrer">《Codex 中文手册》</a>。</li><li><strong>想看同期另一条前沿方向</strong>：<a href="https://daiw.org/manual/jev" target="_blank" rel="noreferrer">《Jev 原理与应用》</a>。</li></ul>',18)])])}const f=t(n,[["render",o]]);export{m as __pageData,f as default};
